// Joueur ou MJ : bascule le jukebox local. S'il joue → on le coupe (la musique
// du Gardien reprend) ; sinon on choisit une playlist et un mode.
const J = game.modules.get('coc7-dialogues')?.api?.jukebox;
if (!J) return ui.notifications.warn('coc7-dialogues 0.10.0+ requis.');
if (J.isPlaying()) return J.stop();
const playlists = game.playlists.contents.filter(p => p.sounds.size);
if (!playlists.length) return ui.notifications.warn('Aucune playlist disponible.');
const opts = playlists.map(p => `<option value="${p.uuid}">${p.name}</option>`).join('');
const content = `<div class="form-group"><label>Playlist</label><select name="pl">${opts}</select></div>
<div class="form-group"><label>Mode</label><select name="mode"><option value="">Celui de la playlist</option><option value="shuffle">Aléatoire</option><option value="sequential">Séquentiel</option><option value="simultaneous">Simultané</option></select></div>`;
const choice = await foundry.applications.api.DialogV2.prompt({
  window: { title: 'Jukebox' }, content,
  ok: { label: 'Lancer', icon: 'fa-solid fa-play', callback: (ev, btn) => ({ uuid: btn.form.elements.pl.value, mode: btn.form.elements.mode.value || null }) }
});
if (choice?.uuid) J.start(choice.uuid, { mode: choice.mode });

// MJ : liste les joueurs connectés qui ont un jukebox en cours.
const J = game.modules.get('coc7-dialogues')?.api?.jukebox;
if (!J) return ui.notifications.warn('coc7-dialogues 0.10.0+ requis.');
const l = J.listActive();
if (!l.length) return ui.notifications.info('🎷 Aucun jukebox en cours.');
const rows = l.map(e => `<li><strong>${e.characterName ?? e.userName}</strong> — ${e.playlist} (${e.track ?? '…'})</li>`).join('');
ChatMessage.create({ content: `<p>🎷 Jukebox en cours :</p><ul>${rows}</ul>`, whisper: game.users.filter(u => u.isGM).map(u => u.id) });

// MJ : coupe tous les jukebox (et toute musique locale) chez tous les joueurs
// et fait reprendre la playlist du Gardien en cours, partout.
const api = game.modules.get('coc7-dialogues')?.api;
if (!api?.resyncMusicForEveryone) return ui.notifications.warn('coc7-dialogues 0.8.0+ requis (monde relancé depuis la mise à jour).');
api.resyncMusicForEveryone();

// RESET des dialogues pour l'utilisateur qui clique (test/debug) :
// - efface sa mémoire de dialogues (variables + nœuds visités, jets ratés)
// - retire de SON journal de quêtes les quêtes données par des dialogues
const api = game.modules.get('coc7-dialogues')?.api;
if (!api) return ui.notifications.warn('coc7-dialogues requis.');
await api.resetState();
const log = api.findQuestLog();
let removed = 0;
if (log) {
  const given = log.pages.filter(p => p.getFlag('coc7-dialogues', 'questSource'));
  removed = given.length;
  if (removed) await log.deleteEmbeddedDocuments('JournalEntryPage', given.map(p => p.id));
}
ui.notifications.info(`🧹 Dialogues remis à zéro pour ${game.user.name}` + (removed ? ` (${removed} quête(s) retirée(s)).` : '.'));

// MJ : transforme la/les tuile(s) sélectionnée(s) (PNJ détouré) en région de
// dialogue de la même forme, behavior « ARK — Dialogue » + portrait = image.
const api = game.modules.get('coc7-dialogues')?.api;
if (!api?.promptTileToDialogueRegion) return ui.notifications.warn('coc7-dialogues 0.12.0+ requis.');
const tiles = canvas.tiles.controlled.map(t => t.document);
if (!tiles.length) return ui.notifications.warn('Sélectionnez au moins une tuile (calque Tuiles).');
api.promptTileToDialogueRegion(tiles);
